export const hasDocument = typeof document !== "undefined";

/**
 *
 * @returns
 */
export function getLastScript() {
  if (hasDocument && document.readyState === "loading") {
    const scripts = document.querySelectorAll("script[src]");
    const lastScript = scripts[scripts.length - 1];
    return lastScript;
  }
  return undefined;
}

/**
 *
 * @returns
 */
export function getCurrentScript() {
  return hasDocument && (document.currentScript || getLastScript());
}

/**
 *
 * @param id
 * @returns
 */
export function startsWithDotSlash(id: string) {
  return id && id.startsWith("./");
}

/**
 * Push `elem` into the array at `obj[k]`, creating the array if needed.
 *
 * @param obj
 * @param k
 * @param elem
 * @param isDup - predicate identifying an existing entry as a duplicate of
 *   `elem`. Required whenever `elem` is a freshly built object, since the
 *   default check is reference equality and would never match.
 * @returns true if the element was added
 */
export function addElementToArrayInObject<T>(
  obj: T,
  k: string,
  elem: unknown,
  isDup?: (existing: any) => boolean
): boolean {
  const arr: unknown[] = obj[k] || (obj[k] = []);
  const dup = isDup ? arr.some(isDup) : arr.includes(elem);
  if (dup) {
    return false;
  }
  arr.push(elem);
  return true;
}

/**
 *
 * @param obj
 * @returns first key of the object
 */
export function firstObjectKey(obj: any) {
  return Object.keys(obj)[0];
}

/**
 *
 * @param name
 * @returns container id
 */
export function containerNameToId(name: string): string {
  const containerSigPrefix = "__mf_container_";

  if (name.startsWith(containerSigPrefix)) {
    return name;
  }
  return containerSigPrefix + name;
}

/**
 *
 * @param T
 * @returns new object
 */
export function createObject<T = any>(): T {
  return Object.create(null);
}
